namespace sv_83d7995819e04c5ba16344bb42615e1b.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeService
{
    public ThemeMode CurrentTheme { get; private set; } = ThemeMode.System;

    public string AccentColor { get; private set; } = "#007bff";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        AccentColor = color;
        OnChange?.Invoke();
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="badge bg-secondary me-3">
    @GetThemeIcon() @ThemeService.CurrentTheme | Accent: @ThemeService.AccentColor
</span>
<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme" title="Toggle theme">🔄</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void CycleTheme()
    {
        var next = ThemeService.CurrentTheme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _ => ThemeMode.System
        };
        ThemeService.SetTheme(next);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>Settings</h1>

<div class="mb-4">
    <h4>Theme Mode</h4>
    <p>Current: <strong>@ThemeService.CurrentTheme</strong></p>
    @foreach (var mode in Enum.GetValues<ThemeMode>())
    {
        <div class="form-check">
            <input class="form-check-input" type="radio" name="themeMode"
                   id="theme-@mode"
                   checked="@(ThemeService.CurrentTheme == mode)"
                   @onchange="() => ThemeService.SetTheme(mode)" />
            <label class="form-check-label" for="theme-@mode">@mode</label>
        </div>
    }
</div>

<div class="mb-4">
    <h4>Accent Color</h4>
    <p>Current: <span style="color: @ThemeService.AccentColor; font-weight: bold;">@ThemeService.AccentColor</span></p>
    <div class="input-group" style="max-width: 300px;">
        <input type="color" class="form-control form-control-color" value="@ThemeService.AccentColor"
               @onchange="OnAccentColorChanged" title="Choose accent color" />
        <input type="text" class="form-control" value="@ThemeService.AccentColor"
               @onchange="OnAccentColorChanged" />
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString();
        if (!string.IsNullOrWhiteSpace(value))
        {
            ThemeService.SetAccentColor(value);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

